import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Arrotondare gli angoli di una foto richiede solo pochi minuti. Carichi l’immagine, trascini un cursore per impostare la curva e scarichi il risultato ammorbidito.</p>\n<p>Questa guida pratica ti accompagna in tutto il procedimento, passo passo. Copre il cursore del raggio, il controllo per singolo angolo, la scorciatoia Cerchio completo, le scelte di riempimento e i formati di esportazione che mantengono gli angoli trasparenti.</p>\n<p>Alla fine saprai creare un avatar arrotondato, un’immagine per card o un banner a forma di pillola su qualsiasi dispositivo. Conserva la foto originale finché non hai controllato il risultato.</p>\n<h2 id=\"before-you-start\">Prima di iniziare: scegli la forma</h2>\n<p>Decidi quale forma ti serve prima di aprire lo strumento. Un cerchio va bene per un avatar, un leggero arrotondamento per una card e una pillola per un banner o un badge.</p>\n<p>Controlla anche la destinazione. Uno spazio per il profilo può richiedere un cerchio, mentre una card di blog può aver bisogno solo dei due angoli superiori arrotondati.</p>\n<p>Usa la foto originale, non una copia compressa. Arrotondare da un originale nitido mantiene lisci i bordi curvi, mentre arrotondare una copia morbida rende le curve ruvide.</p>\n<p>Apri lo strumento <a href=\"/it/arrotonda-angoli-immagine/\">Arrotonda angoli immagine</a> nel browser. Tutto funziona in locale, quindi la tua foto non viene mai caricata su un server.</p>\n<h2 id=\"step-by-step\">Arrotonda gli angoli in cinque passaggi</h2>\n<p>Il procedimento è lo stesso per un leggero arrotondamento e per un cerchio completo. Carica, imposta il raggio, scegli il riempimento, controlla l’anteprima e scarica.</p>\n<p>Prenditi il tempo necessario per il raggio. Una piccola variazione del valore può cambiare molto la sensazione della forma, quindi guarda l’anteprima mentre trascini.</p>\n<ol>\n<li>Carica l’immagine trascinandola nella zona di caricamento, scegliendola dal dispositivo oppure incollando uno screenshot con Ctrl+V.</li>\n<li>Trascina il cursore Raggio di tutti gli angoli per impostare la curva, guardando il valore in pixel in tempo reale mentre lo regoli.</li>\n<li>Attiva la modalità per singolo angolo per impostare raggi diversi, oppure usa la scorciatoia Cerchio completo / Pillola per una forma rotonda o a pillola.</li>\n<li>Scegli Trasparente sotto Riempimento angoli esterni per angoli invisibili, oppure Colore pieno per uno sfondo colorato.</li>\n<li>Scegli il formato di esportazione, PNG o WebP per mantenere la trasparenza, poi clicca Scarica per salvare il risultato.</li>\n</ol>\n<p>Apri il file scaricato una volta prima di usarlo. Conferma che gli angoli siano lisci e che non sia stato tagliato nulla di importante.</p>\n<h2 id=\"setting-radius\">Impostare il raggio degli angoli</h2>\n<p>Il cursore del raggio controlla quanto sono rotondi gli angoli. Un valore piccolo dà un leggero ammorbidimento, mentre un valore grande trasforma gli angoli in curve profonde.</p>\n<p>Un raggio tra 10 e 20 pixel va bene per card, miniature e screenshot. L’arrotondamento è discreto e l’immagine sembra ancora un rettangolo dai bordi morbidi.</p>\n<p>Un raggio tra 50 e 100 pixel dà un aspetto chiaramente arrotondato. Va bene per avatar, post social e grafiche per app, dove la forma fa parte del design.</p>\n<p>Guarda il valore in pixel in tempo reale accanto al cursore. Mostra il raggio esatto, così puoi riprodurre lo stesso arrotondamento su un’altra immagine in futuro.</p>\n<h2 id=\"per-corner-mode\">Usare la modalità per singolo angolo</h2>\n<p>La modalità per singolo angolo permette di impostare un raggio diverso per ogni angolo. Attivala e compaiono quattro cursori separati, uno per ogni angolo dell’immagine.</p>\n<p>La card di un blog è il caso classico. Arrotonda i due angoli in alto e lascia squadrati i due in basso, così la foto sta benissimo in cima alla card.</p>\n<p>Disattivando la modalità si torna a un unico raggio per tutti gli angoli. I valori singoli vengono conservati mentre la modalità è spenta, così puoi riattivarla senza perderli.</p>\n<p>Usa il controllo per singolo angolo con moderazione. Un design con quattro raggi diversi sembra un errore, mentre uno o due angoli arrotondati e gli altri squadrati sembrano una scelta precisa.</p>\n<h2 id=\"full-circle-shortcut\">Usare la scorciatoia Cerchio completo / Pillola</h2>\n<p>La scorciatoia Cerchio completo imposta il raggio a metà della dimensione dell’immagine con un solo clic. Su una foto quadrata crea un cerchio perfetto, su un rettangolo crea una pillola.</p>\n<p>Per un cerchio pulito, ritaglia prima la foto in formato 1:1. Una fonte quadrata con la scorciatoia dà un avatar perfettamente rotondo, adatto a qualsiasi spazio per il profilo.</p>\n<p>Su una foto rettangolare, la scorciatoia crea una pillola: un rettangolo con le estremità completamente arrotondate. Le pillole vanno bene per pulsanti, badge e banner.</p>\n<p>Controlla il risultato prima di scaricare. Una pillola può sembrare elegante, ma può anche tagliare contenuti importanti ai lati di una foto larga.</p>\n<h2 id=\"choosing-fill\">Scegliere trasparenza o colore pieno</h2>\n<p>Quando gli angoli vengono tagliati, lo spazio vuoto va riempito. La trasparenza lascia gli angoli invisibili, mentre il colore pieno li riempie con un colore.</p>\n<p>Scegli la trasparenza per grafiche web, avatar e overlay. L’immagine si fonde con qualsiasi sfondo, perché gli angoli lasciano vedere ciò che sta dietro.</p>\n<p>Scegli il colore pieno quando la destinazione non gestisce la trasparenza. Un riempimento bianco fa sembrare l’immagine una foto arrotondata su una card bianca, e va bene per documenti e stampe.</p>\n<p>Se clicchi la trasparenza mentre è selezionato il JPG, lo strumento cambia formato in automatico. Il JPG non ha trasparenza, quindi ti sposta su PNG o WebP.</p>\n<h2 id=\"choosing-format\">Scegliere il formato di esportazione</h2>\n<p>Scegli il PNG per il risultato più nitido con trasparenza. È senza perdite, quindi i bordi curvi restano lisci, e funziona ovunque, compresi i browser vecchi.</p>\n<p>Scegli il WebP quando vuoi file piccoli con trasparenza. Dà file più piccoli del PNG con gli stessi angoli invisibili, anche se alcuni sistemi più vecchi lo rifiutano.</p>\n<p>Scegli il JPG solo quando gli angoli hanno un colore pieno. Il JPG non ha trasparenza, quindi un’esportazione trasparente in JPG riceve un colore pieno, che potrebbe non abbinarsi allo sfondo.</p>\n<p>Per le grafiche web arrotondate, PNG o WebP sono la scelta giusta. Per una foto arrotondata su una pagina bianca, il JPG con riempimento bianco va benissimo.</p>\n<h2 id=\"previewing\">Controllare l’anteprima prima di scaricare</h2>\n<p>Controlla sempre l’anteprima prima di scaricare. Verifica che gli angoli siano lisci, che il raggio sembri giusto e che non sia stato tagliato nulla di importante.</p>\n<p>Ingrandisci un angolo e guarda la curva. Un arco liscio significa che l’arrotondamento ha funzionato bene, mentre un bordo seghettato significa che la fonte era troppo piccola o troppo morbida.</p>\n<p>Controlla il riempimento sullo sfondo dove vivrà l’immagine. Un angolo trasparente sta bene ovunque, mentre un colore pieno si abbina solo al colore per cui è stato impostato.</p>\n<p>Se il raggio non ti convince, regola il cursore e controlla di nuovo. Una piccola variazione del valore può cambiare molto la sensazione della forma.</p>\n<h2 id=\"rounding-for-avatar\">Arrotondare gli angoli per un avatar</h2>\n<p>Ritaglia prima la foto in quadrato, usando lo strumento <a href=\"/it/ritaglia-immagini/\">Ritaglia immagini</a>. Un ritaglio 1:1 con il viso al centro è il miglior punto di partenza per un avatar rotondo.</p>\n<p>Carica la foto quadrata e clicca la scorciatoia Cerchio completo. Il raggio salta a metà della dimensione dell’immagine e la foto diventa un cerchio perfetto.</p>\n<p>Tieni il viso ben dentro l’inquadratura. Gli angoli vengono tagliati, quindi un viso vicino al bordo può perdere un orecchio o parte dei capelli per colpa della curva.</p>\n<p>Esporta in PNG o WebP. La trasparenza mantiene gli angoli invisibili, così l’avatar si fonde con qualsiasi sfondo del profilo, chiaro o scuro.</p>\n<h2 id=\"rounding-for-cards\">Arrotondare gli angoli per card e interfacce</h2>\n<p>Fai corrispondere il raggio della foto a quello della card. Una foto con un raggio di 16 pixel dentro una card con un raggio di 16 pixel sembra un unico elemento, mentre raggi diversi sembrano trascuratezza.</p>\n<p>Per una card di blog, arrotonda i due angoli superiori e lascia squadrati i due inferiori. Attiva la modalità per singolo angolo, imposta i raggi in alto e lascia a zero quelli in basso.</p>\n<p>Mantieni lo stesso raggio in tutte le card di un insieme. Una griglia di card con angoli uguali sembra professionale, mentre raggi misti sembrano casuali.</p>\n<p>Esporta le immagini per card in PNG o WebP quando la card sta su uno sfondo colorato. La trasparenza mantiene gli angoli puliti su qualsiasi colore.</p>\n<h2 id=\"rounding-screenshots\">Arrotondare gli angoli di uno screenshot</h2>\n<p>Incolla uno screenshot direttamente con Ctrl+V per saltare il passaggio del salvataggio. L’immagine compare subito nello strumento, pronta da arrotondare.</p>\n<p>Usa un raggio piccolo, tra 10 e 20 pixel, per gli screenshot. Un leggero arrotondamento fa sembrare la cattura una card moderna, senza nascondere nulla del contenuto.</p>\n<p>Esporta gli screenshot arrotondati in PNG. Il formato senza perdite mantiene nitido il testo piccolo, e questo conta quando lo screenshot mostra un’impostazione o un messaggio di errore.</p>\n<p>Mantieni lo stesso raggio in tutti gli screenshot di una guida. Angoli uguali aiutano il lettore a seguire i passaggi, mentre raggi misti distraggono dalle istruzioni.</p>\n<h2 id=\"rounding-on-mobile\">Arrotondare gli angoli da telefono o tablet</h2>\n<p>Lo strumento funziona sui touchscreen, quindi puoi arrotondare una foto direttamente dal telefono che l’ha scattata. Caricala dalla galleria, trascina il cursore del raggio e scarica il risultato.</p>\n<p>Usa la scorciatoia Cerchio completo per gli avatar su uno schermo piccolo. Un tocco trasforma una foto quadrata in un cerchio, più in fretta che trascinare il cursore fino al valore esatto.</p>\n<p>Controlla l’anteprima a dimensione intera prima di scaricare. Un raggio che sullo schermo piccolo del telefono sembra discreto può risultare più evidente se visto da un computer.</p>\n<p>I file scaricati finiscono nella solita cartella dei download. Da lì puoi impostare l’immagine arrotondata come foto profilo o condividerla direttamente.</p>\n<h2 id=\"troubleshooting\">Risolvere i problemi più comuni dell’arrotondamento</h2>\n<p>Se gli angoli mostrano uno sfondo bianco invece della trasparenza, controlla il formato di esportazione. Il JPG non ha trasparenza, quindi esporta in PNG o WebP per mantenere gli angoli invisibili.</p>\n<p>Se la forma è una pillola invece di un cerchio, la foto di partenza è rettangolare. Ritagliala in quadrato prima di applicare la scorciatoia Cerchio completo.</p>\n<p>Se gli angoli sembrano seghettati, l’immagine di partenza potrebbe essere troppo piccola. Parti da un originale a risoluzione più alta e le curve risulteranno lisce.</p>\n<p>Se i valori per singolo angolo sono spariti, controlla se hai spento la modalità. I valori vengono conservati mentre la modalità è spenta, quindi riattivandola tornano come prima.</p>\n<h2 id=\"combining-with-border\">Combinare angoli arrotondati e bordo</h2>\n<p>Arrotonda prima gli angoli, poi aggiungi un bordo con lo strumento <a href=\"/it/aggiungi-bordo-immagine/\">Aggiungi bordo all’immagine</a>. Lo strumento per i bordi legge la forma dell’immagine, quindi arrotondare prima mantiene la cornice allineata.</p>\n<p>Fai corrispondere il raggio del bordo a quello degli angoli. Un bordo con un raggio di 16 pixel intorno a una foto con un raggio di 16 pixel sembra un unico elemento.</p>\n<p>Per un effetto card, usa un bordo sottile con un raggio leggero. La combinazione sembra una card moderna di un’app, e va bene per post social e presentazioni.</p>\n<p>Per uno stile Polaroid, tieni gli angoli squadrati. Il classico aspetto della pellicola istantanea ha gli angoli netti, e arrotondarli rovina l’effetto retrò.</p>\n<h2 id=\"quick-tips\">Consigli rapidi per angoli arrotondati migliori</h2>\n<p>Ritaglia nella forma giusta prima di arrotondare. Un ritaglio quadrato per un cerchio, uno largo per una pillola e uno da card per un’immagine di blog partono tutti dallo strumento di ritaglio.</p>\n<p>Guarda l’anteprima a dimensione intera prima di scaricare. Ingrandisci gli angoli e conferma che le curve siano lisce e che non sia stato tagliato nulla di importante.</p>\n<p>Salva il file arrotondato con un nome chiaro, per esempio avatar-cerchio.png. Potresti aver bisogno della stessa forma un’altra volta, e un nome chiaro ti evita di rifare il lavoro.</p>\n<p>Conserva la foto originale senza arrotondamento. Una volta che gli angoli sono stati tagliati in un’esportazione, non si possono più recuperare da quel file.</p>\n<h2 id=\"rounding-for-social-post\">Arrotondare gli angoli per un post social</h2>\n<p>Un post social con gli angoli arrotondati sembra moderno e accogliente. I bordi morbidi si abbinano alle card e ai pulsanti dell’app intorno, così l’immagine si fonde con l’interfaccia.</p>\n<p>Usa un raggio da piccolo a medio per i post nel feed. Un leggero arrotondamento, tra 10 e 20 pixel, ammorbidisce l’immagine senza cambiarne il carattere o nascondere contenuti.</p>\n<p>Mantieni lo stesso raggio in tutti i tuoi post. Un feed in cui ogni immagine condivide la stessa forma degli angoli sembra curato, mentre raggi misti sembrano casuali.</p>\n<p>Esporta le immagini social in JPG quando gli angoli hanno un colore pieno, oppure in PNG e WebP quando sono trasparenti. Il formato giusto mantiene gli angoli puliti su qualsiasi sfondo.</p>\n<h2 id=\"rounding-for-presentation\">Arrotondare gli angoli per una presentazione</h2>\n<p>Le foto sulle slide stanno meglio con gli angoli arrotondati. I bordi morbidi si abbinano al design moderno delle slide, e l’immagine sembra un elemento voluto, non un rettangolo incollato.</p>\n<p>Fai corrispondere il raggio della foto al tema delle slide. Un mazzo di slide con card da 16 pixel ha bisogno di foto con un raggio di 16 pixel, così immagini e card si allineano.</p>\n<p>Tieni il raggio piccolo per le slide proiettate in grande. Un raggio enorme su uno schermo grande può dominare l’immagine, mentre un leggero arrotondamento resta discreto a qualsiasi dimensione.</p>\n<p>Esporta le immagini per presentazioni in JPG ad alta qualità quando gli angoli hanno un colore pieno. La foto deve restare nitida quando viene proiettata, e un’esportazione a bassa qualità ammorbidisce le curve.</p>\n<p>Per il confronto, leggi <a href=\"/it/blog/angoli-arrotondati-vs-ritaglio-circolare/\">Angoli arrotondati o ritaglio circolare: avatar e card</a>. Per la panoramica completa, leggi <a href=\"/it/blog/arrotondare-angoli-immagine-guida-completa/\">Arrotondare gli angoli di un’immagine: guida completa</a>. Per incorniciare una foto arrotondata, prova lo strumento <a href=\"/it/aggiungi-bordo-immagine/\">Aggiungi bordo all’immagine</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Come arrotondo gli angoli di una foto dal telefono?","answer":"Apri lo strumento Arrotonda angoli immagine nel browser del telefono, carica la foto dalla galleria e trascina il cursore del raggio con il dito. Usa la scorciatoia Cerchio completo per un avatar rotondo. Esporta in PNG o WebP per mantenere gli angoli trasparenti."},{"question":"Qual è il raggio migliore per l’immagine di una card?","answer":"Un raggio da piccolo a medio, tra 10 e 20 pixel, va bene per quasi tutte le card: ammorbidisce senza cambiare la forma. Fai corrispondere il raggio della foto a quello della card per un effetto perfetto. Per una card di blog, arrotonda i due angoli in alto e lascia squadrati i due in basso."},{"question":"Posso arrotondare gli angoli di un’immagine JPG?","answer":"Sì, ma gli angoli verranno riempiti con un colore pieno, perché il JPG non ha trasparenza. Scegli un colore di riempimento uguale allo sfondo dove vivrà l’immagine, oppure esporta in PNG o WebP per mantenere gli angoli invisibili."},{"question":"Come sostituisco l’immagine senza perdere le impostazioni del raggio?","answer":"Carica la nuova immagine con l’opzione di sostituzione dello strumento, che mantiene le impostazioni attuali di raggio e riempimento. Puoi poi regolare il raggio per la nuova foto ed esportarla con la stessa configurazione."},{"question":"Perché gli angoli arrotondati sembrano seghettati?","answer":"L’immagine di partenza è probabilmente troppo piccola o troppo morbida, quindi la curva si disegna come una serie di gradini visibili. Parti da un originale a risoluzione più alta e i bordi risulteranno lisci. Anche esportare in PNG aiuta, perché è un formato senza perdite."},{"question":"Arrotondare gli angoli cambia la larghezza e l’altezza della foto?","answer":"No. L’arrotondamento taglia solo le zone agli angoli e lascia invariate larghezza e altezza. Il file mantiene le stesse dimensioni in pixel, con gli angoli trasparenti oppure riempiti con un colore pieno."}];
